const { createClient } = require('@supabase/supabase-js');

class WS {
  constructor(imvu) {
    this.imvu = imvu;
    this.ws = null;
  }

  async connect(api) {

    const supabase = createClient(api.ssv, api.ssk, {
      global: { headers: { Authorization: `Bearer ${api.ws_key}` } }
    });

    supabase.realtime.setAuth(api.ws_key)

    // Break change, new supabase version returns a promise
    const channel = await supabase.channel(api.ws_sv, { config: { private: true } });
    this.ws = channel
    channel
      .on('broadcast', { event: '*' }, (data) => {

        const { payload } = data
        const user = payload.data?.user ? this.imvu.users.getById(payload.data.user.id) : null
        const furniture = payload.data?.furniture ? this.imvu.furnitures.getById(payload.data.furniture.instance_id) : null

        if (payload.type === 'join') {
          this.imvu.users.addJson(payload.data)
        }
        if (payload.type === 'ping') {
          this.send({ "type": 'pong' })
        }
        if (payload.type === 'leave') {
          if (user) {
            this.imvu.users.remove(user.id)
          }
        }
        if (payload.type === 'seat') {
          // I flipped a coin and it told me to use 'user' instead of 'furniture', both work
          user?.observeFurniture(furniture?.instance_id, payload.data.seat_num);
        }

        if (payload.type === 'furniture_update') {
          if (furniture) {
            furniture.updated = true
            //Why not?
            this.imvu.emit('furniture_update', furniture)
          }
        }
        if (payload.type === 'message') {
          if (user) {
            if (!payload.data.content.startsWith('*')) {
              // Yes, it's just filtering out messages that don't start with '*'
              this.imvu.emit('chat', { content: payload.data.content, user });
            }
            this.imvu.emit('message', { content: payload.data.content, user });
          }
        }

      })
      .subscribe((status, err) => {
        if (status === 'SUBSCRIBED') {
          this.send({ auth: true })
        } else {
          throw new Error('Error: WS error');
        }
      });

    this.imvu.on('furniture_remove', furniture => {
      this.send({
        type: 'furniture',
        action: 'delete',
        furniture: { instance_id: furniture.instance_id }
      });
    })

    this.imvu.on('furniture_add', furniture => {
      this.send({
        type: 'furniture',
        action: 'add',
        furniture: furniture
      });
    });
    this.imvu.on('furniture_set', furniture => {
      this.send({
        type: 'furniture',
        action: 'set',
        furniture: furniture
      });
    });


  }

  send(data) {
    if (this.ws) {
      this.ws.send({
        type: 'broadcast',
        event: 'user',
        payload: data,
      })
    }
  }

  close() {
    if (this.ws) {
      this.ws.unsubscribe();
    }
  }
}

module.exports = WS;
